import { test, expect } from '@playwright/test';

test.describe('Data Refresh After Mutation', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com'); // Replace with the actual URL
  });

  test('should display updated data after mutation', async ({ page }) => {
    await page.getByRole('button', { name: 'Trigger Mutation' }).click();
    await page.waitForResponse(response => response.url().includes('/api/mutate') && response.status() === 200);

    const updatedData = await page.getByText('Updated Data'); // Replace with the actual text to verify
    await expect(updatedData).toBeVisible();
  });

  test('should refresh data automatically after mutation', async ({ page }) => {
    await page.getByRole('button', { name: 'Trigger Mutation' }).click();
    await page.waitForResponse(response => response.url().includes('/api/mutate') && response.status() === 200);

    await page.waitForTimeout(5000); // Wait for automatic refresh
    const refreshedData = await page.getByText('Refreshed Data'); // Replace with the actual text to verify
    await expect(refreshedData).toBeVisible();
  });
});
